<script lang="ts">
 import {surface} from './surfaces';
 import {CheckpointWriter,EDITOR_CHECKPOINT,type EditorCheckpoint,type CheckpointState} from '../core/editor-checkpoint';
 import {onMount,tick} from 'svelte';
 import {formatText,type Format} from './text-edit';
 import AppearancePicker from './AppearancePicker.svelte';
 import {noteText} from './note-share';
 import RichText from './RichText.svelte';
 import {resolveAtom} from '../core/note-references';
 let options=$state(false),appearanceOpen=$state(false),aliasesOpen=$state(false),shareOpen=$state(false),shareMessage=$state('');
 async function share(markdown:boolean,copy=false){try{const text=noteText(draft.title||'',draft.content||'',markdown);if(!copy&&navigator.share)await navigator.share({title:draft.title||'',text});else{await navigator.clipboard.writeText(text);shareMessage='Скопировано';}}catch(e){if((e as Error).name!=='AbortError')error=(e as Error).message;}}
 let visual=$state<RichText>();let raw=$state(false);

 import type {Atom,Snapshot,AtomState} from '../core/model';
 import type {AtomType} from '../plugins/api';
 import {normalize} from '../core/core';
 import {type Candidate,type Rejection} from '../core/matching';
 import {GraphWorkerClient} from '../graph/worker-client';
 import type {Preferences} from '../core/preferences';
 import type {StorageAdapter} from '../core/model';
 let {initial,data,types,parent,prefs,section,storage,recovery,onopen,onsave,onclose,ondelete}:{initial:Partial<Atom>;data:Snapshot;types:AtomType[];parent?:string;prefs:Preferences;section:string;storage:StorageAdapter;recovery?:EditorCheckpoint;onopen:(id:string)=>void;onsave:(draft:Partial<Atom>&{title:string},add:{to:string;relation:string;source?:string}[],remove:string[],keepOpen?:boolean)=>Promise<Atom>;onclose:()=>void;ondelete:(id:string)=>Promise<void>}=$props();
 const recovered=(()=>recovery)();
 const seed=(()=>JSON.parse(JSON.stringify(initial)) as Partial<Atom>)();
 let draft=$state<Partial<Atom>>(recovered?{...$state.snapshot(recovered.draft),appearance:{...recovered.draft.appearance}}:{...seed,appearance:{...seed.appearance},aliases:[...(seed.aliases||[])]});
 let matchAtoms=$state.raw<Atom[]>([]);
 $effect(()=>{matchAtoms=$state.snapshot(data.atoms);});
 let matcher=$state<GraphWorkerClient|null>(null);let matches=$state<Candidate[]>([]);let matchVersion=0;
 let rejection=$state<Rejection|undefined>();
 let aliases=$state(recovered?.aliases??(seed.aliases||[]).join(', '));let linkQuery=$state('');let relation=$state('related');let add=$state<{to:string;relation:string;source?:string}[]>(recovered?.add||[]);let remove=$state<string[]>(recovered?.remove||[]);let saving=$state(false);let error=$state('');let checkpointState=$state<CheckpointState>('clean');let viewportHeight=$state<number|undefined>();let viewportTop=$state<number|undefined>();let confirmDelete=$state((()=>section==='delete')());let titleInput:HTMLInputElement;let form:HTMLFormElement;let textArea=$state<HTMLTextAreaElement>(null!);let expanded=$state(false);let quickLinks=$state(false);let quickQuery=$state('');let quickInput=$state<HTMLInputElement>(null!);let selection={start:0,end:0};
 const labels:Record<AtomState,string>={normal:'Обычные',now:'Сейчас',paused:'Отложить',archived:'Архив'};
 const offeredTypes=$derived(types.filter(t=>t.id!=='task'&&t.id!=='builtin.templates:task'));
 const currentType=$derived(offeredTypes.find(t=>t.id===draft.type||t.id.startsWith('builtin.templates:')&&t.id.split(':').pop()===draft.type));
 const original=JSON.stringify({draft:seed,aliases:(seed.aliases||[]).join(', ')});
 const dirty=()=>JSON.stringify({draft:$state.snapshot(draft),aliases})!==original||add.length>0||remove.length>0;
 const linked=$derived(data.links.filter(l=>(l.from===draft.id||l.to===draft.id)&&!remove.includes(l.id)));
 const candidates=$derived.by(()=>{const excluded=new Set([draft.id||'',parent||'',...linked.flatMap(l=>[l.from,l.to]),...add.map(l=>l.to),...data.links.filter(l=>remove.includes(l.id)).flatMap(l=>[l.from,l.to])]);const q=normalize(linkQuery);if(q)return data.atoms.filter(a=>!excluded.has(a.id)&&[a.title,...a.aliases].some(t=>normalize(t).includes(q))).slice(0,6).map(atom=>({atom,confidence:1,reason:'title' as const}));if(prefs.linkMode==='off')return[];return matches.filter(c=>!excluded.has(c.atom.id)).slice(0,6);});

 $effect(()=>{const text=(draft.title||'')+' '+(draft.content||'');const atoms=matchAtoms,suppression=$state.snapshot(rejection),enabled=prefs.linkMode!=='off';const version=++matchVersion;if(!matcher||!enabled){matches=[];return;}const worker=matcher;const timer=setTimeout(()=>worker.call<Candidate[]>('match',{text,atoms,exclude:[draft.id||''],rejection:suppression}).then(result=>{if(version===matchVersion)matches=result;}).catch(e=>error=e.message),180);return()=>clearTimeout(timer);});
 const writer=(()=>new CheckpointWriter(storage,e=>error=e.message,state=>checkpointState=state))();
 function recoveryValue():EditorCheckpoint|null{return dirty()?{version:1,initial:seed,draft:$state.snapshot(draft),aliases,add:$state.snapshot(add),remove:$state.snapshot(remove),parent}:null;}
 // Capture large text only when the debounce fires, rather than cloning it per keystroke.
 $effect(()=>{draft.title;draft.content;draft.type;draft.state;draft.paused;JSON.stringify(draft.appearance);draft.importance;aliases;add.length;remove.length;writer.schedule(recoveryValue);});
 export async function checkpoint(){writer.schedule(recoveryValue);await writer.flush();}
 async function discard(){try{writer.cancel();await writer.flush();await storage.transaction([{kind:'setting',key:EDITOR_CHECKPOINT,value:null}]);onclose();return true;}catch(e){error=(e as Error).message;return false;}}
 function dismiss(){if(shareOpen)shareOpen=false;else if(appearanceOpen)appearanceOpen=false;else if(options)options=false;else if(aliasesOpen)aliasesOpen=false;else if(quickLinks)quickLinks=false;else if(confirmDelete)confirmDelete=false;else close();}
 function close(){if(saving)return;saving=true;void discard().finally(()=>saving=false);}
 async function navigate(id:string){if(!dirty()||await save())onopen(id);}
 async function format(kind:Format){await tick();if(!raw){visual?.format(kind);return;}const edit=formatText(draft.content||'',selection.start,selection.end,kind);draft.content=edit.text;await tick();textArea.focus();textArea.setSelectionRange(edit.start,edit.end);selection={start:edit.start,end:edit.end};}
 async function showLinks(){quickLinks=!quickLinks;quickQuery='';if(quickLinks){await tick();quickInput.focus();}}
 async function insertLink(atom:Atom){const target=typeof (atom.properties.vault as {path?:string})?.path==='string'?(atom.properties.vault as {path:string}).path.replace(/\.md$/i,''):atom.title;const value=`[[${target}${target!==atom.title?'|'+atom.title:''}]]`;const content=draft.content||'';if(raw)draft.content=content.slice(0,selection.start)+value+content.slice(selection.end);else{await tick();visual?.insertWiki(value,target,atom.title);}if(!linked.some(l=>l.from===atom.id||l.to===atom.id)&&!add.some(l=>l.to===atom.id))add=[...add,{to:atom.id,relation:'related',source:'markdown'}];const caret=selection.start+value.length;selection={start:caret,end:caret};quickLinks=false;await tick();if(raw){textArea.focus();textArea.setSelectionRange(caret,caret);}else visual?.focus();}
 async function edit(){await tick();if(raw)textArea?.focus();else visual?.focus();}
 function openWiki(target:string){const atom=resolveAtom(target.split('#')[0],draft as Atom,data.atoms);if(atom)void navigate(atom.id);}
 function saveInput(){return {...$state.snapshot(draft),title:(draft.title||'').trim()||Array.from((draft.content||'').trim().split('\n')[0].replace(/^[#>*\s-]+/,'')).slice(0,120).join('')||'Без названия',aliases:aliases.split(',').map(x=>x.trim()).filter(Boolean),properties:$state.snapshot(draft.properties)||{}};}
 async function save(){if(saving)return false;if(!dirty())return discard();saving=true;error='';try{
 if(!(draft.title||'').trim()&&!(draft.content||'').trim()&&!draft.id)return await discard();
 await checkpoint();writer.cancel();await onsave(saveInput(),$state.snapshot(add),$state.snapshot(remove));return true;
 }catch(e){error=(e as Error).message;return false;}finally{saving=false;}}
 function prepareDelete(){if(!saving)confirmDelete=true;}

 function applyType(id:string){const t=types.find(t=>t.id===id);draft.type=id.startsWith('builtin.templates:')?id.split(':').pop()!:id;if(t){draft.appearance={...draft.appearance,...t.appearance,icon:t.icon};if(!draft.content&&t.content)draft.content=t.content;}}
 function keyboard(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&['b','i','k'].includes(e.key.toLowerCase())){e.preventDefault();e.stopPropagation();if(e.key.toLowerCase()==='k')showLinks();else format(e.key.toLowerCase()==='b'?'bold':'italic');return;}if(e.key==='Escape'){e.preventDefault();dismiss();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();save();}if(e.key==='Tab'){const els=[...form.querySelectorAll<HTMLElement>('button:not([disabled]),input,textarea,select,[tabindex="0"]')].filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}}
 onMount(()=>{matcher=new GraphWorkerClient();if(section==='links')options=true;if(section==='appearance')appearanceOpen=true;if(section==='text')void edit();else if(seed.id)form.focus();else titleInput.focus();if(draft.id)storage.getSetting<Rejection>('rejected:'+draft.id).then(value=>rejection=value).catch(e=>error=e.message);const background=()=>{if(document.hidden)void checkpoint().catch(()=>{});};const hide=()=>{void checkpoint().catch(()=>{});};document.addEventListener('visibilitychange',background);window.addEventListener('pagehide',hide);const viewport=window.visualViewport,resizeViewport=()=>{viewportHeight=viewport?.height;viewportTop=viewport?.offsetTop;};resizeViewport();viewport?.addEventListener('resize',resizeViewport);viewport?.addEventListener('scroll',resizeViewport);const unload=(e:BeforeUnloadEvent)=>{if(dirty()&&checkpointState!=='saved'){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',unload);return()=>{matchVersion++;matcher?.close();writer.cancel();document.removeEventListener('visibilitychange',background);window.removeEventListener('pagehide',hide);window.removeEventListener('beforeunload',unload);viewport?.removeEventListener('resize',resizeViewport);viewport?.removeEventListener('scroll',resizeViewport);};});
</script>
<div class="scrim note-scrim" style:height={viewportHeight?`${viewportHeight}px`:undefined} style:top={viewportTop!==undefined?`${viewportTop}px`:undefined} style:bottom={viewportHeight?'auto':undefined} use:surface={{close:dismiss,blocked:()=>saving}}>
 <!-- svelte-ignore a11y_no_noninteractive_element_to_interactive_role (The form is a focus-trapped editor dialog.) -->
 <form class="editor note-editor" class:expanded tabindex="-1" bind:this={form} role="dialog" aria-modal="true" aria-label="Редактор атома" onsubmit={e=>{e.preventDefault();save();}} onkeydown={keyboard}>
 <div class="row note-heading"><div class="editor-shortcuts"><button type="button" class="icon-button" aria-label="Поделиться заметкой" aria-expanded={shareOpen} onclick={()=>{shareOpen=!shareOpen;options=false;}}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15V3m-4 4 4-4 4 4M7 10H4v11h16V10h-3"/></svg></button><button type="button" class="icon-button" aria-label="Меню заметки" aria-expanded={options} onclick={()=>{options=!options;shareOpen=false;}}>⋯</button></div><div class="button-wrap"><button type="submit" class="primary note-save" disabled={saving||confirmDelete}>{saving?'Сохраняем…':'Готово'}</button><button type="button" class="icon-button expand-editor" aria-label={expanded?'Свернуть редактор':'Развернуть редактор'} aria-pressed={expanded} onclick={()=>expanded=!expanded}>{expanded?'↙':'↗'}</button><button type="button" disabled={saving} onclick={close}>Отмена</button></div></div>
 {#if shareOpen}<section class="note-share" aria-label="Поделиться"><strong>Поделиться заметкой</strong><div><button type="button" onclick={()=>share(false)}>Текст</button><button type="button" onclick={()=>share(true)}>Markdown</button></div><div><button type="button" onclick={()=>share(false,true)}>Копировать текст</button><button type="button" onclick={()=>share(true,true)}>Копировать Markdown</button></div><small role="status">{shareMessage}</small></section>{/if}
 {#if error}<p role="alert" class="inline-error">{error}</p>{/if}
 <div class="note-fields" inert={saving||confirmDelete}>
 {#if options}<section class="note-options"><h3>Связи и действия</h3>{#if candidates.length}<div class="inline-suggestions"><small>Связать</small>{#each candidates as c}<button type="button" class="suggestion" onclick={()=>{add=[...add,{to:c.atom.id,relation:relation.trim()||'related'}];linkQuery='';}}>+ {c.atom.title}<small>{c.confidence<1?Math.round(c.confidence*100)+'%':''}</small></button>{/each}</div>{/if}
 <details open={section==='links'} class="links-section"><summary>Связи</summary><div class="row"><small>СВЯЗИ</small><span class="muted">{linked.length+add.length+(parent?1:0)}</span></div>
 {#if parent}<p class="link-chip">↗ {data.atoms.find(a=>a.id===parent)?.title} <small>контекст</small></p>{/if}
 {#each linked as l}{@const other=data.atoms.find(a=>a.id===(l.from===draft.id?l.to:l.from))}<div class="link-chip"><span>{l.from===draft.id?'↗':'↙'} {other?.title}<small>{l.relation==='related'?'связано':l.relation}{other?.state==='archived'?' · архив':''}</small></span><button type="button" aria-label={`Удалить связь с ${other?.title}`} onclick={()=>remove=[...remove,l.id]}>×</button></div>{/each}
 {#each add as l,i}<div class="link-chip"><span>↗ {data.atoms.find(a=>a.id===l.to)?.title}<small>{l.relation==='related'?'связано':l.relation} · новая</small></span><button type="button" aria-label="Отменить новую связь" onclick={()=>add=add.filter((_,j)=>i!==j)}>×</button></div>{/each}
 <input aria-label="Связать с атомом" placeholder="Найти существующий атом…" bind:value={linkQuery}/>
 {#if linkQuery}<input aria-label="Смысл связи" placeholder="Смысл связи" bind:value={relation} maxlength="100"/>{/if}

 </details>
 <div class="note-metadata details-body">{#if draft.paused}<button type="button" onclick={()=>draft.paused=false}>Возобновить</button>{/if}


 {#if draft.id}<button type="button" class="subtle" onclick={prepareDelete}>Удалить атом</button>{/if}
 <small class="muted">{draft.created_at?new Date(draft.created_at).toLocaleString():''}</small>
 </div></section>{/if}
 <input class="atom-title" bind:this={titleInput} enterkeyhint="next" onkeydown={async e=>{if(e.key==='Enter'){e.preventDefault();await edit();}}} aria-label="Название" placeholder="О чём вы думаете?" bind:value={draft.title} maxlength="500"/>
 <div class="note-toolbar"><label><select aria-label="Тип" value={currentType?.id||draft.type} onchange={e=>applyType(e.currentTarget.value)}>{#each offeredTypes as t}<option value={t.id}>{t.name}</option>{/each}{#if !currentType}<option value={draft.type} disabled>{draft.type==='task'||draft.type==='builtin.templates:task'?'Задача (устаревший тип)':draft.type==='note'?'Заметка':draft.type}</option>{/if}</select></label><label class="state-pill"><svg viewBox="0 0 24 24" aria-hidden="true">{#if draft.state==='now'}<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>{:else if draft.state==='archived'}<path d="M4 4h16v4H4zM6 8v12h12V8M10 12h4"/>{:else}<circle cx="12" cy="12" r="7"/>{/if}</svg><select aria-label="Состояние" bind:value={draft.state}>{#each Object.entries(labels).filter(([s])=>s!=='paused') as [s,label]}<option value={s}>{label}</option>{/each}</select></label><label class="importance-pill"><select aria-label="Важность" bind:value={draft.importance} onchange={()=>draft.appearance={...draft.appearance,size_override:undefined}}><option value={0}>Обычная</option><option value={1}>Важная</option><option value={2}>Главная</option></select></label><div class="editor-modes" role="group" aria-label="Режим редактора"><button type="button" class="preview-toggle" aria-pressed={!raw} onclick={()=>{raw=false;void edit();}}>Обычный</button><button type="button" class="preview-toggle" aria-pressed={raw} onclick={()=>{raw=true;void edit();}}>Markdown</button></div></div>
 <div class="note-quick-actions"><button type="button" aria-expanded={appearanceOpen} onclick={()=>appearanceOpen=!appearanceOpen}>Оформление</button><button type="button" aria-expanded={aliasesOpen} onclick={()=>aliasesOpen=!aliasesOpen}>Другие имена</button></div>{#if aliasesOpen}<label class="stack">Алиасы<input aria-label="Алиасы" placeholder="Другие имена через запятую" bind:value={aliases}/></label>{/if}{#if appearanceOpen}<section class="editor-appearance"><AppearancePicker bind:value={draft.appearance!} title={draft.title||''}/></section>{/if}
 <div class="writing-tools" onpointerdown={e=>e.preventDefault()} tabindex="-1" role="toolbar" aria-label="Форматирование текста"><button type="button" aria-label="Жирный" title="Жирный · Ctrl+B" onclick={()=>format('bold')}><b>B</b></button><button type="button" aria-label="Курсив" title="Курсив · Ctrl+I" onclick={()=>format('italic')}><i>I</i></button><button type="button" aria-label="Заголовок" onclick={()=>format('heading')}>H</button><button type="button" aria-label="Список" onclick={()=>format('list')}>≡</button><button type="button" aria-label="Чек-лист" onclick={()=>format('checkbox')}>☐</button><button type="button" aria-label="Список задач" onclick={()=>format('task')}>☑</button><button type="button" aria-label="Цитата" onclick={()=>format('quote')}>❞</button><button type="button" aria-label="Код" onclick={()=>format('code')}>‹›</button></div>
 {#if quickLinks}<div class="quick-link-picker"><input bind:this={quickInput} aria-label="Быстрая связь" placeholder="Найти заметку…" bind:value={quickQuery}/>{#each data.atoms.filter(a=>a.id!==draft.id&&normalize(a.title+' '+a.aliases.join(' ')).includes(normalize(quickQuery))).slice(0,8) as atom}<button type="button" onclick={()=>insertLink(atom)}>{atom.title}</button>{/each}</div>{/if}
 {#if !raw}<RichText bind:this={visual} value={draft.content||''} onchange={content=>draft.content=content} onwiki={openWiki} disabled={saving||confirmDelete}/>{:else}<textarea bind:this={textArea} oninput={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} onselect={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} onkeyup={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} onclick={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} class="note-content" aria-label="Текст" placeholder="Пишите свободно…" bind:value={draft.content}></textarea>{/if}

 </div>
 {#if confirmDelete}<div class="confirm"><p>Удалить атом и его связи? Локальная копия останется в настройках.</p><button type="button" disabled={saving} onclick={async()=>{saving=true;try{writer.cancel();await writer.flush();await ondelete(draft.id!);await storage.transaction([{kind:'setting',key:EDITOR_CHECKPOINT,value:null}]);}catch(e){error=(e as Error).message;}finally{saving=false;}}}>Удалить</button><button type="button" onclick={()=>confirmDelete=false}>Отмена</button></div>{/if}
 <div class="editor-draft-status" role="status">{checkpointState==='pending'?'Сохраняем черновик…':checkpointState==='saved'?'Черновик сохранён на устройстве':''}</div>
 </form>
</div>
<style>
 .editor-shortcuts{display:flex;align-items:center;margin-right:auto}.editor-shortcuts svg,.state-pill svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex:none}
 .note-editor .note-heading{padding:6px 0 10px;border-bottom:1px solid var(--theme-border);margin-bottom:0}.note-editor{gap:10px}.note-editor .atom-title{padding:6px 0;font-size:26px}.note-fields{gap:8px}
 .note-editor .note-toolbar{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.25fr) minmax(0,1fr);gap:6px}.note-toolbar>label{min-width:0;gap:4px;flex:initial;justify-content:center}.note-toolbar select{width:100%;max-width:100%;padding:4px 6px;min-height:36px}.note-toolbar .state-pill{padding:0 6px;gap:3px}.note-toolbar .state-pill select{width:100%;max-width:100%;min-width:0;min-height:36px}.editor-modes{grid-column:1/-1;margin:2px 0 0}
 .note-quick-actions{display:flex;gap:4px}.note-quick-actions button{background:transparent;border:0;color:var(--theme-muted);padding:6px 10px;min-height:36px;font-size:12px}.note-share{display:flex;flex-direction:column;gap:8px;padding:12px;border:1px solid var(--theme-border);border-radius:16px}.note-share small{letter-spacing:0}.note-share>div{display:flex;gap:6px;flex-wrap:wrap}.note-options{padding:12px;max-height:45dvh;overflow:auto;border:1px solid var(--theme-border);border-radius:16px;background:var(--theme-surfaceAlt)}.note-options h3{margin:4px 0}.editor-appearance{padding:8px}
 @media(max-width:650px){.note-editor .note-heading{padding-top:2px}.note-toolbar .editor-modes{margin:2px 0 0}.note-editor .atom-title{font-size:25px}.note-editor .note-content{height:clamp(220px,42dvh,500px)}}
</style>
